package org.node.flyconsole;

import org.json.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Real FDB/CPU plus a synthetic outcome criterion; no commercial-game learning claim. */
public final class PairedEvaluationCheck {
    interface Action{void run()throws Exception;}
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static void fails(Action action,String why)throws Exception{boolean bad=false;try{action.run();}catch(Exception expected){bad=true;}check(bad,why);}
    static void erase(File file)throws Exception{if(file.isDirectory())for(File child:file.listFiles())erase(child);Files.deleteIfExists(file.toPath());}
    static JSONArray ids(Graph graph,int[] ports){JSONArray a=new JSONArray();for(int i:ports)a.put(Long.toString(graph.ids[i]));return a;}
    static JSONObject set(Graph graph,boolean trained)throws Exception {
        int[] inputs=FdbLearningCheck.sources(),outputs=Arrays.copyOf(FdbLearningCheck.targets(),8);GraphDelta layer=new GraphDelta(graph.ids.length,2048);if(trained)layer.addEdge(0,16,127);
        FdbLearning learning=new FdbLearning(graph,layer,inputs,outputs,.05,16,127,false,"base");learning.seed(1);
        JSONObject lc=new JSONObject().put("enabled",true).put("rate",.05).put("maxEdges",16).put("maxWeight",127).put("trainBase",false).put("plasticityMode","base").put("creditProfile","single-v1");
        JSONArray edges=new JSONArray();for(GraphDelta.Edge e:layer.edges())edges.put(new JSONObject().put("source",Long.toString(graph.ids[e.source])).put("target",Long.toString(graph.ids[e.target])).put("weight",e.weight));
        JSONObject fdb=new JSONObject().put("version",3).put("graph_sha256",graph.fingerprint()).put("deltas",new JSONArray()).put("edges",edges).put("neuronDynamics",FdbCheckpoint.thresholdState(layer,graph)).put("learning",lc).put("learningState",FdbCheckpoint.save(learning,graph,inputs,outputs));
        JSONObject cfg=new JSONObject().put("inputs",ids(graph,inputs)).put("outputs",ids(graph,outputs)).put("mode","closed").put("maxHz",500).put("thresholdHz",10).put("windowMs",100).put("gain",1).put("disableInhibition",false).put("scramble",false).put("seed",1).put("systemButtons","auto").put("lesions",new JSONArray()).put("backend","cpu").put("controllerSource","exo").put("gmode","off").put("fdb",fdb);
        return new JSONObject().put("type","fly-layer-set").put("id",UUID.randomUUID().toString()).put("layerVersion",2).put("name","synthetic fixture").put("system","nes").put("romHash","a".repeat(64)).put("graph",new JSONObject().put("sha256",graph.fingerprint())).put("configuration",cfg).put("profile",new JSONObject()).put("runtime",new JSONObject().put("clock","lockstep")).put("policy",new JSONObject()).put("createdAt",1).put("updatedAt",1).put("notes","").put("journal",new JSONArray());
    }
    static JSONArray plan(int offset,int count)throws Exception {
        JSONArray plan=new JSONArray();for(int i=0;i<count;i++){String origin=UUID.randomUUID().toString(),hash=String.format("%064x",offset+i);plan.put(new JSONObject().put("originId",origin).put("groupId",origin).put("stateHash",hash).put("startFrame",100+i).put("seed",1).put("role","control").put("trained",false).put("lineage",new JSONObject().put("origins",new JSONArray().put(origin)).put("states",new JSONArray().put(hash))));}return plan;
    }
    static JSONObject protocol()throws Exception{return new JSONObject().put("signature","b".repeat(64)).put("profileSha256","c".repeat(64)).put("actuatorSha256","d".repeat(64)).put("timing","lockstep-1x").put("actionsHash",CheckpointDigest.of(new JSONObject().put("actions",new JSONArray().put(0).put(1)))).put("feedbackTrusted",true);}
    static JSONObject complete(PairedEvaluation pair,JSONObject live,EvaluationArchive archive,ComparisonStore store)throws Exception {
        JSONObject result=null;for(int leg=0;leg<2;leg++){
            for(int i=0;i<pair.reservation.getJSONArray("plan").length();i++){
                JSONObject start=new JSONObject(pair.reservation.getJSONArray("plan").getJSONObject(i).toString()).put("generation",leg*100+i);pair.arm(start,live,7);
                boolean retention=start.getString("evidenceKind").equals("retention"),second=pair.reservation.getJSONObject("reference").getJSONObject("configuration").getJSONObject("fdb").getJSONArray("edges").length()>0;
                int stimulus=second&&!retention?1:0;
                JSONObject request=new JSONObject().put("token",i+1).put("generation",leg*100+i).put("originId",start.getString("originId")).put("frame",start.getLong("startFrame")+1).put("manualMask",0).put("learningMode","eval").put("controllerSource","exo").put("gmode","off").put("runtimeClock","lockstep").put("emulationRate",1).put("actions",new JSONArray().put(0).put(1));JSONArray retina=new JSONArray();for(int j=0;j<16;j++)retina.put(j==stimulus?1:0);request.put("retina",retina);
                JSONObject sample=pair.sample(request,live,7,new AtomicBoolean());int mask=sample.getJSONObject("fdbDecision").getInt("mask");check(mask==(leg==0||retention?1:0),"separate real CPU networks produce learned vs baseline actions and retain earlier behavior");
                pair.trial(new JSONObject().put("outcome",mask==1?"success":"death").put("confidence","diagnostic"),live,7);
            }
            result=pair.end(live,7,archive,store,false);if(leg==0)check(result.getString("nextLeg").equals("reference"),"candidate proof persisted before reference starts");
        }return result;
    }
    public static void main(String[] args)throws Exception {
        File root=Files.createTempDirectory("paired-evaluation-").toFile();try{
            Graph graph=FdbLearningCheck.graph();JSONObject candidate=set(graph,true),reference=set(graph,false),live=candidate.getJSONObject("configuration").getJSONObject("fdb");String liveDigest=CheckpointDigest.of(live);float[] w0=graph.weights.clone();
            JSONObject wide=new JSONObject(candidate.toString()).put("system","sega");check(new IsolatedFdbContext(graph,wide).experiment.agentButtonMask==4095,"wide platforms retain native control mask even with legacy eight-output checkpoints");wide.getJSONObject("configuration").put("systemButtons","blocked");check(new IsolatedFdbContext(graph,wide).experiment.agentButtonMask==2039,"wide blocked system buttons match native runtime");
            LearnedRoles roles=new LearnedRoles(new File(root,"roles"));JSONObject domain=LearnedRoles.context(candidate);roles.checkpoint(reference);JSONObject before=roles.checkpoint(candidate);check(roles.reference(domain).getString("role").equals("baseline"),"unconfirmed initial checkpoint is baseline, never Best");
            ComparisonStore store=new ComparisonStore(new File(root,"comparisons"));EvaluationArchive archive=new EvaluationArchive(new File(root,"evaluations"));JSONArray plan=plan(1,8);JSONObject reservation=store.reserve(protocol(),candidate,reference,null,new JSONArray(),plan);
            check(reservation.getJSONObject("context").getDouble("alpha")==.005,"first preregistered comparison has a fixed family-wise error budget");
            fails(()->new ComparisonStore(new File(root,"comparisons")).reserve(protocol(),candidate,reference,null,new JSONArray(),plan),"spent control cannot be reused after process reopen, even before first inference");
            JSONArray alias=new JSONArray(plan.toString());alias.getJSONObject(0).put("groupId",UUID.randomUUID().toString());fails(()->store.reserve(protocol(),candidate,reference,null,new JSONArray(),alias),"renamed / merged groups cannot evade consumed origin/state lineage");
            PairedEvaluation pair=new PairedEvaluation(graph,reservation,live,7);JSONObject result=complete(pair,live,archive,store);check(result.getBoolean("complete"),"both isolated legs completed");
            check(CheckpointDigest.of(live).equals(liveDigest)&&Arrays.equals(graph.weights,w0),"live Current and shared W0 unchanged by both legs");check(roles.status(domain).isNull("best"),"proof itself does not mutate roles");
            ComparisonStore.Promotion verified=store.conclude(pair.id,archive,result.getJSONObject("candidateArchive"),result.getJSONObject("referenceArchive"));check(verified!=null,"actual isolated frozen pair passes synthetic criterion");
            JSONObject promoted=roles.promote(verified);String best=promoted.getString("best");check(promoted.getString("current").equals(before.getString("current")),"promotion leaves live Current checkpoint pointer intact");check(promoted.getString("recovery").equals(before.getString("recovery")),"promotion preserves Recovery");
            check(new LearnedRoles(new File(root,"roles")).status(domain).getString("best").equals(best),"verified Best survives process reopen");check(roles.reference(domain).getJSONArray("coverage").length()==8,"Best retains the entire heldout task coverage");
            fails(()->roles.promote(verified),"stale comparison cannot replace a newer Best");
            fails(()->store.reserve(protocol(),candidate,reference,best,roles.reference(domain).getJSONArray("coverage"),plan(100,8)),"new candidate must include all earlier Best tasks for retention");
            JSONObject later=new JSONObject(candidate.toString()).put("updatedAt",2);later.getJSONObject("configuration").getJSONObject("fdb").getJSONObject("learningState").put("observations",2);JSONObject checkpoint=roles.checkpoint(later);check(checkpoint.getString("best").equals(best),"later Current learning never rotates Best away");
            File rolesDir=new File(root,"roles").listFiles(File::isDirectory)[0];File proof=Arrays.stream(rolesDir.listFiles()).filter(f->f.getName().startsWith("evidence-")&&!f.getName().contains("recovery")).findFirst().get();Files.writeString(proof.toPath(),"damaged");check(roles.status(domain).getString("best").equals(best),"independent proof backup preserves confirmed Best after corruption");
            File quota=new File(root,"roles/quota-fixture");try(RandomAccessFile file=new RandomAccessFile(quota,"rw")){file.setLength(LearnedRoles.MAX_BYTES);}fails(()->roles.checkpoint(new JSONObject(later.toString()).put("updatedAt",3)),"quota failure cannot silently rotate roles");check(roles.status(domain).getString("best").equals(best),"Best retained when generation store full");Files.delete(quota.toPath());
            JSONObject next=new JSONObject(candidate.toString()).put("updatedAt",4);next.getJSONObject("configuration").getJSONObject("fdb").getJSONArray("edges").put(new JSONObject().put("source","2").put("target","17").put("weight",127));JSONObject nextLive=next.getJSONObject("configuration").getJSONObject("fdb");roles.checkpoint(next);
            JSONArray expanded=new JSONArray(plan.toString()),fresh=plan(1000,12);for(int i=0;i<fresh.length();i++)expanded.put(fresh.getJSONObject(i));JSONObject secondReservation=store.reserve(protocol(),next,candidate,best,roles.reference(domain).getJSONArray("coverage"),expanded);check(secondReservation.getJSONArray("plan").getJSONObject(0).getString("evidenceKind").equals("retention"),"reused old tasks count only as retention, never new statistical evidence");
            PairedEvaluation secondPair=new PairedEvaluation(graph,secondReservation,nextLive,7);JSONObject secondResult=complete(secondPair,nextLive,archive,store);ComparisonStore.Promotion secondVerified=store.conclude(secondPair.id,archive,secondResult.getJSONObject("candidateArchive"),secondResult.getJSONObject("referenceArchive"));check(secondVerified!=null,"fresh improvement plus no forgetting is confirmed against existing Best");
            File fallback=new File(rolesDir,"manifest.recovery.json");byte[] previousFallback=Files.readAllBytes(fallback.toPath());Files.delete(fallback.toPath());fallback.mkdir();Files.writeString(new File(fallback,"block").toPath(),"blocked");fails(()->roles.promote(secondVerified),"failed atomic fallback commit must not replace confirmed Best");check(roles.status(domain).getString("best").equals(best),"only working Best remains reachable after failed promotion");erase(fallback);Files.write(fallback.toPath(),previousFallback);
            JSONObject secondBest=roles.promote(secondVerified);check(secondBest.getString("previousBest").equals(best),"previous confirmed Best remains separately protected");check(roles.reference(domain).getJSONArray("coverage").length()==20,"successive Best carries old plus new task coverage");String latestBest=secondBest.getString("best");
            JSONObject interrupted=store.reserve(protocol(),candidate,reference,null,new JSONArray(),plan(300,8));PairedEvaluation aborted=new PairedEvaluation(graph,interrupted,live,7);check(!aborted.end(live,7,archive,store,true).getBoolean("complete"),"abort records failure without promotion");fails(()->store.reserve(protocol(),candidate,reference,null,new JSONArray(),interrupted.getJSONArray("plan")),"aborted holdout is consumed durably");
            PairedEvaluation changed=new PairedEvaluation(graph,store.reserve(protocol(),candidate,reference,null,new JSONArray(),plan(400,8)),live,7);JSONObject corrupted=new JSONObject(live.toString()).put("counter",99);fails(()->changed.arm(new JSONObject(changed.reservation.getJSONArray("plan").getJSONObject(0).toString()).put("generation",1),corrupted,7),"changed live Current aborts isolated comparison");
            JSONObject untrusted=protocol().put("feedbackTrusted",false),unknown=store.reserve(untrusted,candidate,reference,null,new JSONArray(),plan(500,8));PairedEvaluation unconfirmed=new PairedEvaluation(graph,unknown,live,7);JSONObject no=complete(unconfirmed,live,archive,store);check(store.conclude(unconfirmed.id,archive,no.getJSONObject("candidateArchive"),no.getJSONObject("referenceArchive"))==null,"untrusted game criterion never promotes even with perfect synthetic outcomes");
            JSONObject diagnostic=store.reserve(protocol().put("criterionType","fly-nes-target-v1").put("criterionHorizon",10),candidate,reference,null,new JSONArray(),plan(600,1));PairedEvaluation observed=new PairedEvaluation(graph,diagnostic,live,7);JSONObject measured=null;
            for(int leg=0;leg<2;leg++){
                JSONObject start=new JSONObject(diagnostic.getJSONArray("plan").getJSONObject(0).toString()).put("generation",leg+1);observed.arm(start,live,7);
                for(int i=0;i<(leg==0?1:10);i++){JSONArray retina=new JSONArray();for(int j=0;j<16;j++)retina.put(0);observed.sample(new JSONObject().put("token",i+1).put("generation",leg+1).put("originId",start.getString("originId")).put("frame",start.getLong("startFrame")+i+1).put("manualMask",0).put("learningMode","eval").put("controllerSource","exo").put("runtimeClock","lockstep").put("emulationRate",1).put("retina",retina).put("actions",new JSONArray().put(0).put(1)).put("gameFeedback",new JSONObject().put("kind","fly-nes-target-v1").put("x",leg==0?200:20).put("y",100)),live,7,new AtomicBoolean());}
                observed.trial(new JSONObject().put("outcome",leg==0?"death":"success").put("confidence","configured").put("boundary",leg==0?"terminal":"limit"),live,7);measured=observed.end(live,7,archive,store,false);
                if(leg==0)check(measured.getJSONObject("candidateProof").getJSONArray("trials").getJSONObject(0).getString("outcome").equals("success"),"native diagnostic RAM, not frontend label, determines success");
            }
            check(measured.getJSONObject("proof").getJSONArray("trials").getJSONObject(0).getString("outcome").equals("not-reached"),"verified fixed horizon non-success remains evaluation-only, distinct from death and unknown");check(CheckpointDigest.of(live).equals(liveDigest),"fixed horizon evaluation never applies negative learning feedback");
            JSONObject wrongReservation=store.reserve(protocol(),next,reference,latestBest,new JSONArray(),plan(700,16));PairedEvaluation wrongReference=new PairedEvaluation(graph,wrongReservation,nextLive,7);JSONObject wrongResult=complete(wrongReference,nextLive,archive,store);ComparisonStore.Promotion wrongProof=store.conclude(wrongReference.id,archive,wrongResult.getJSONObject("candidateArchive"),wrongResult.getJSONObject("referenceArchive"));check(wrongProof!=null,"statistical fixture alone cannot authorize replacing an existing Best");fails(()->roles.promote(wrongProof),"even a passing archived pair must compare against the actual prior Best");check(roles.status(domain).getString("best").equals(latestBest),"wrong reference cannot replace Best");
            JSONObject ref=result.getJSONObject("candidateArchive");File archived=new File(root,"evaluations/"+ref.getString("id")+".json");Files.writeString(archived.toPath(),"damaged");fails(()->store.conclude(pair.id,archive,ref,result.getJSONObject("referenceArchive")),"promotion cannot consume damaged archived proof");check(roles.status(domain).getString("best").equals(latestBest),"independent role proof survives external archive damage");
            System.out.println("PASS: actual CPU/FDB isolated candidate and reference, unchanged live Current/W0, durable preregistration and spent lineage, paired archive verification, atomic proven Best, persistent baseline/retention/Recovery, stale promotion, abort, quota, corruption and untrusted-result rejection (synthetic outcome fixture)");
        }finally{erase(root);}
    }
}
